def emit(event):
    data = (json.dumps(event, ensure_ascii=True) + "\n").encode()
    done = 0
    while done < len(data):
        n = os.write(journal_fd, data[done:])
        if n <= 0:
            raise RuntimeError("journal write made no progress; partial raw quarantined")
        done += n
def metadata(value):
    return {key: getattr(value, key) for key in ["st_dev", "st_ino", "st_mode", "st_uid", "st_gid", "st_nlink", "st_size", "st_mtime_ns", "st_ctime_ns"]}
def save_json(name, value):
    path = OUT / name
    emit({"event": "output_open_intent", "name": name})
    fd = os.open(path, os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    known[fd] = {"role": "new_owned_output", "name": name}
    primary = None
    result = None
    try:
        before = metadata(os.fstat(fd))
        raw = (json.dumps(value, ensure_ascii=True, indent=2) + "\n").encode()
        h = hashlib.sha256(raw).hexdigest()
        done = 0
        while done < len(raw):
            n = os.write(fd, raw[done:done + 65536])
            if n <= 0:
                raise RuntimeError("output write made no progress; partial raw quarantined")
            done += n
        os.fsync(fd)
        os.lseek(fd, 0, os.SEEK_SET)
        check = hashlib.sha256()
        count = 0
        while True:
            chunk = os.read(fd, 65536)
            if not chunk:
                break
            check.update(chunk)
            count += len(chunk)
        after = metadata(os.fstat(fd))
        assert stat.S_ISREG(after["st_mode"]) and count == len(raw) == after["st_size"] and check.hexdigest() == h
        assert (before["st_dev"], before["st_ino"]) == (after["st_dev"], after["st_ino"])
        result = {"name": name, "bytes": count, "sha256": h, "before": before, "after": after, "same_saved_output_FD_stream_match": True}
    except BaseException as error:
        primary = error
        emit({"event": "output_primary_error", "name": name, "kind": type(error).__name__, "text": str(error)})
    try:
        os.close(fd)
        del known[fd]
        emit({"event": "output_close_return", "fd": fd, "name": name})
    except BaseException as error:
        emit({"event": "output_close_unknown", "fd": fd, "name": name, "kind": type(error).__name__, "text": str(error)})
        if primary is None:
            primary = error
    if primary is not None:
        raise primary
    emit({"event": "output_saved", **result})
    return result

